import React from "react";
import { BrowserRouter as Router, Routes, Route, Navigate } from "react-router-dom";
import { AuthPage, ProfilePage, ProtectedRoute, Layout } from "./components";
import ProfessionalEmployeeDashboard from "./components/ProfessionalEmployeeDashboard";
import ProfessionalManagerDashboard from "./components/ProfessionalManagerDashboard";
import RoleBasedRedirect from "./components/RoleBasedRedirect";
import TripDebugger from "./components/TripDebugger";
import "./styles.css";

function App() {
  return (
    <Router>
      <div className="App">
        <Routes>
          {/* Public Routes with Layout */}
          <Route path="/login" element={<Layout><AuthPage /></Layout>} />
          <Route path="/register" element={<Layout><AuthPage /></Layout>} />

          {/* Protected Routes with Layout */}
          <Route 
            path="/profile" 
            element={
              <ProtectedRoute>
                <Layout>
                  <ProfilePage />
                </Layout>
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/employee-dashboard" 
            element={
              <ProtectedRoute>
                <Layout>
                  <ProfessionalEmployeeDashboard />
                </Layout>
              </ProtectedRoute>
            } 
          />
          <Route 
            path="/manager-dashboard" 
            element={
              <ProtectedRoute>
                <Layout>
                  <ProfessionalManagerDashboard />
                </Layout>
              </ProtectedRoute>
            } 
          />
          {/* Legacy Routes - Redirect to new dashboards */}
          <Route path="/upload" element={<Navigate to="/employee-dashboard" replace />} />
          <Route path="/upload-bill" element={<Navigate to="/employee-dashboard" replace />} />
          <Route path="/enhanced-upload" element={<Navigate to="/employee-dashboard" replace />} />
          <Route path="/budget" element={<Navigate to="/employee-dashboard" replace />} />
          {/* Debug Route */}
          <Route 
            path="/debug" 
            element={
              <ProtectedRoute>
                <Layout>
                  <TripDebugger />
                </Layout>
              </ProtectedRoute>
            } 
          />
          {/* Default redirect based on user role */}
          <Route 
            path="/" 
            element={
              <ProtectedRoute>
                <Layout>
                  <RoleBasedRedirect />
                </Layout>
              </ProtectedRoute>
            } 
          />
          <Route 
            path="*" 
            element={
              <ProtectedRoute>
                <Layout>
                  <RoleBasedRedirect />
                </Layout>
              </ProtectedRoute>
            } 
          />
        </Routes>
      </div>
    </Router>
  );
}

export default App;
